  "city.doppel-parlor.description": "Phòng khách bên cạnh Viện nghiên cứu Trung tâm Doppel. Khách được mời ngồi và nhận từng trang nhật ký nghiên cứu.",
  "city.doppel-lab.description": "Viện nghiên cứu nội bộ nằm sâu trong viện nghiên cứu của Doppel. Những cuốn nhật ký do các nhà nghiên cứu từng được cử đến Eternal để lại tập trung ở đây.",
  "city.doppel-lab.displayName": "Doppel · Viện nghiên cứu nội bộ",
  "city.doppel-office.description": "Phòng quản lý của Doppel, nơi tổng hợp thành quả nghiên cứu và công dụng của relic. Phê duyệt phải qua nhiều cấp nên chờ rất lâu.",
  "city.doppel-office.displayName": "Doppel · Phòng quản lý",
  "city.rust-garage.description": "Xưởng bảo trì của Rust. Các yêu cầu sửa thiết bị nghiên cứu hỏng đổ về không ngớt.",
  "city.rust-garage.displayName": "Rust · Xưởng bảo trì",
  "city.rust-lease.description": "Phòng quản lý cho thuê của Rust, nơi cho thuê thiết bị hiệu năng cao. Chỉ một lần gia hạn cũng kéo theo cuộc thương lượng dài.",
  "city.rust-lease.displayName": "Rust · Phòng quản lý cho thuê",
  "city.doppel-upper.description": "Tầng cao nhất của viện nghiên cứu Doppel. Những người quyết định mục đích nghiên cứu ngồi ở đây.",
  "city.doppel-upper.displayName": "Doppel · Tầng lãnh đạo",
  "city.rust-works.description": "Xưởng đúc khổng lồ ở trung tâm Rust. Việc thiết kế và sửa chữa thiết bị nghiên cứu đều tụ về một nơi.",
  "city.rust-works.displayName": "Rust · Xưởng đúc trung tâm",
  "city.odidi-embassy.description": "Phòng tiếp kiến nơi Odidi, thành phố nghiên cứu giấc mơ, đón khách bên ngoài. Đề nghị luôn do họ nói trước.",
  "city.odidi-embassy.displayName": "Odidi · Phòng tiếp kiến ngoại giao",
  "journal.interaction-doppel-lab-01.title": "Nhật ký của chuyến công tác không trở về",
  "journal.interaction-doppel-lab-01.body": "Nhật ký của một nhà nghiên cứu từng được cử đến Eternal. Trang cuối chỉ có một dòng \"Người thay thế đã đến\", và ô chữ ký bên dưới vẫn để trống.",
  "city.department.exchange": "Sở giao dịch",
