  "relic.quetzalcoatlus.excavationSite": "Trầm tích sông cuối Kỷ Phấn Trắng, Big Bend, Texas, Hoa Kỳ",
  "relic.quetzalcoatlus.fossilRecord": "Một chuỗi đốt sống cổ rỗng được tìm thấy nối liền thành một hàng trong lớp đá bùn ven sông. Thành xương mỏng như giấy, được cho là để nâng cơ thể lơ lửng trên không, và một mặt trầm tích chỉ còn vết đầu cánh cũng được ghi nhận.",
  "relic.quetzalcoatlus.catalogSummary": "Mẫu vật cỡ lớn dựa trên Quetzalcoatlus với cổ và màng cánh được phục dựng quá mức.",
  "relic.quetzalcoatlus.unlockRecord": "Hồ sơ thảm họa 006. Xuất hiện trên bầu trời bờ sông. Nó khoác áo choàng đen xòe ra như đôi cánh và đội mũ rộng vành nhọn, những món trang sức hình mũi tên đung đưa trên dây xích. Nó nhìn xuống từ trên cao rất lâu rồi lao xuống trong một đòn, và chỉ một cái vỗ cánh đã cuốn trang bị gần đó đi. Chưa xác nhận được nó từ đâu đến và nhắm tới điều gì.",
  "relic.quetzalcoatlus.observation.originYear": "Khoảng 68 triệu năm trước",
  "relic.quetzalcoatlus.observation.restorationYear": "E.C. 18",
  "relic.quetzalcoatlus.observation.lifeStage": "Trưởng thành",
  "relic.quetzalcoatlus.observation.height": "2,15 m",
  "relic.quetzalcoatlus.observation.weight": "92 kg",
  "relic.quetzalcoatlus.passive.desc": "Khi trận đấu mở màn, lao xuống mục tiêu và làm choáng, đồng thời tăng Tỉ lệ chí mạng.",
  "relic.quetzalcoatlus.passive.name": "Săn mồi lao xuống",
