  "relic.raitia-grass.origin": "Chuột sóc",
  "relic.raitia-grass.excavationSite": "Trầm tích hang karst, Slovenia",
  "relic.raitia-grass.fossilRecord": "Hàng chục hộp sọ cùng loài được thu từ một lớp trầm tích hang duy nhất. Năm chiếc trong số đó khớp nhau về kích thước và hàm răng đến mức được xếp vào cùng một lứa.",
  "relic.raitia-grass.catalogSummary": "Mẫu vật dựa trên chuột sóc, được phục hồi với răng cửa và túi má quá khổ.",
  "relic.raitia-grass.squadNote": "Lực lượng tiêu hao của Hủy Diệt. Chúng đồng loạt tràn về hướng được chỉ và lấp kín hành lang, những kẻ phía sau bước thẳng qua chỗ kẻ phía trước ngã xuống.",
  "relic.raitia-grass.researcherTitle": "Nhà nghiên cứu",
  "relic.raitia-grass.unlockRecord": "Hồ sơ nhận dạng 207. Được xác nhận thuộc Hủy Diệt. Trong năm cá thể mặc đồ ngủ có mũ trùm gắn tai chuột, đây là cá thể quấn nút thắt xanh lá; túi hình miếng phô mai, đôi dép có răng và chiếc đuôi sọc buộc ruy băng ở đầu rất nổi bật. Khi tìm thấy thức ăn, nó báo hiệu không bằng tiếng kêu mà bằng tiếng răng cửa, và các chị em nghe thấy liền cùng lúc ùa tới một chỗ. Chỗ nó gặm có chồi non rơi vãi, và dọc đường nó đi, mỗi dấu chân đều nảy mầm từ hạt, để lại một lối xanh. Lý do nó không ngừng ăn dù đã đến mùa ngủ đông vẫn chưa được xác nhận.",
  "relic.raitia-grass.observation.originYear": "Khoảng 2 triệu năm trước",
  "relic.raitia-grass.observation.restorationYear": "E.C. 2",
  "relic.raitia-grass.observation.lifeStage": "Nhỏ tuổi",
  "relic.raitia-grass.observation.height": "0,94 m",
  "relic.raitia-grass.observation.weight": "21 kg",
  "relic.raitia-grass.passive.name": "Ngủ đông",
  "relic.raitia-grass.passive.desc": "Mỗi trận một lần, khi HP còn một nửa trở xuống, hồi 3% HP tối đa mỗi giây trong 5 giây.",
  "relic.raitia-grass.ferocity.name": "Ăn ngấu nghiến",
  "relic.raitia-grass.basic.name": "Gặm răng cửa",
  "relic.raitia-grass.ultimate.name": "Dốc túi má",
  "relic.raitia-grass.projectName": "ANNIHILATION SWARM — Quần thể ăn quá mức",
  "relic.raitia-water.name": "Guttia",
  "relic.raitia-water.origin": "Chuột sóc",
  "relic.raitia-water.excavationSite": "Trầm tích hang karst, Slovenia",
  "relic.raitia-water.fossilRecord": "Hàng chục hộp sọ cùng loài được thu từ một lớp trầm tích hang duy nhất. Năm chiếc trong số đó khớp nhau về kích thước và hàm răng đến mức được xếp vào cùng một lứa.",
  "relic.raitia-water.catalogSummary": "Mẫu vật dựa trên chuột sóc, được phục hồi với răng cửa và túi má quá khổ.",
  "relic.raitia-water.squadNote": "Lực lượng tiêu hao của Hủy Diệt. Chúng đồng loạt tràn về hướng được chỉ và lấp kín hành lang, những kẻ phía sau bước thẳng qua chỗ kẻ phía trước ngã xuống.",
  "relic.raitia-water.researcherTitle": "Nhà nghiên cứu",
  "relic.raitia-water.unlockRecord": "Hồ sơ nhận dạng 208. Được xác nhận thuộc Hủy Diệt. Trong số những cá thể mặc cùng kiểu đồ ngủ có mũ trùm, đây là cá thể có chiếc đuôi sọc xanh dương gắn cục bông ở đầu, cười với một tay chống hông, tay kia đặt ngón lên khóe miệng. Khi nghe tiếng răng cửa của chị em, nó cười và lao ra đầu tiên, tới gần thì gặm bằng răng cửa món trang bị nào nằm trong tầm tay trước. Nơi bầy đi qua, những dấu chân ướt kéo dài thành hàng. Thứ làm ướt những dấu chân ấy vẫn chưa được xác nhận.",
  "relic.raitia-water.observation.originYear": "Khoảng 2 triệu năm trước",
  "relic.raitia-water.observation.restorationYear": "E.C. 2",
  "relic.raitia-water.observation.lifeStage": "Nhỏ tuổi",
  "relic.raitia-water.observation.height": "0,94 m",
  "relic.raitia-water.observation.weight": "21 kg",
  "relic.raitia-water.passive.name": "Ngủ đông",
  "relic.raitia-water.passive.desc": "Mỗi trận một lần, khi HP còn một nửa trở xuống, hồi 3% HP tối đa mỗi giây trong 5 giây.",
  "relic.raitia-water.ferocity.name": "Ăn ngấu nghiến",
