  "relic.raitia-water.ultimate.name": "Dốc túi má",
  "relic.raitia-water.projectName": "ANNIHILATION SWARM — Quần thể ăn quá mức",
  "relic.raitia-fire.name": "Favia",
  "relic.raitia-fire.origin": "Chuột sóc",
  "relic.raitia-fire.excavationSite": "Trầm tích hang karst, Slovenia",
  "relic.raitia-fire.fossilRecord": "Hàng chục hộp sọ cùng loài được thu từ một lớp trầm tích hang duy nhất. Năm chiếc trong số đó khớp nhau về kích thước và hàm răng đến mức được xếp vào cùng một lứa.",
  "relic.raitia-fire.catalogSummary": "Mẫu vật dựa trên chuột sóc, được phục hồi với răng cửa và túi má quá khổ.",
  "relic.raitia-fire.squadNote": "Lực lượng tiêu hao của Hủy Diệt. Chúng đồng loạt tràn về hướng được chỉ và lấp kín hành lang, những kẻ phía sau bước thẳng qua chỗ kẻ phía trước ngã xuống.",
  "relic.raitia-fire.researcherTitle": "Nhà nghiên cứu",
  "relic.raitia-fire.unlockRecord": "Hồ sơ nhận dạng 209. Được xác nhận thuộc Hủy Diệt. Trong số những cá thể mặc cùng kiểu đồ ngủ có mũ trùm, đây là cá thể thắt ruy băng caro hồng, đứng với gương mặt chưa tỉnh hẳn, một tay dụi mắt, tay kia chống hông. Dù trông buồn ngủ, nó không ngừng ăn và vẫn gặm bằng răng cửa dù túi má đã đầy. Khi các chị em ùa đi, nó vừa dụi mắt vừa đi theo sau. Cơn buồn ngủ ấy là giả vờ hay thật vẫn chưa được xác nhận.",
  "relic.raitia-fire.observation.originYear": "Khoảng 2 triệu năm trước",
  "relic.raitia-fire.observation.restorationYear": "E.C. 2",
  "relic.raitia-fire.observation.lifeStage": "Nhỏ tuổi",
  "relic.raitia-fire.observation.height": "0,94 m",
  "relic.raitia-fire.observation.weight": "21 kg",
