  "relic.raitia-fire.passive.desc": "Mỗi trận một lần, khi HP còn một nửa trở xuống, hồi 3% HP tối đa mỗi giây trong 5 giây.",
  "relic.raitia-fire.ferocity.name": "Ăn ngấu nghiến",
