  "relic.raitia-earth.catalogSummary": "Mẫu vật dựa trên chuột sóc, được phục hồi với răng cửa và túi má quá khổ.",
  "relic.raitia-earth.squadNote": "Lực lượng tiêu hao của Hủy Diệt. Chúng đồng loạt tràn về hướng được chỉ và lấp kín hành lang, những kẻ phía sau bước thẳng qua chỗ kẻ phía trước ngã xuống.",
  "relic.raitia-earth.researcherTitle": "Nhà nghiên cứu",
  "relic.raitia-earth.unlockRecord": "Hồ sơ nhận dạng 210. Được xác nhận thuộc Hủy Diệt. Trong số những cá thể mặc cùng kiểu đồ ngủ có mũ trùm, đây là cá thể nổi bật với nền nâu, nút thắt vàng và tóc tết, đầu đuôi mang một cục lông lớn. Khi nó đứng dang tay về phía trước, các chị em đồng loạt đổ theo hướng đầu ngón tay, và chỗ con đi đầu ngã xuống thì con phía sau cứ thế dẫm qua. Ai quyết định hướng mà đầu ngón tay ấy chỉ vẫn chưa được xác nhận.",
