  "relic.raitia-wind.fossilRecord": "Hàng chục hộp sọ cùng loài được thu từ một lớp trầm tích hang duy nhất. Năm chiếc trong số đó khớp nhau về kích thước và hàm răng đến mức được xếp vào cùng một lứa.",
  "relic.raitia-wind.catalogSummary": "Mẫu vật dựa trên chuột sóc, được phục hồi với răng cửa và túi má quá khổ.",
  "relic.raitia-wind.squadNote": "Lực lượng tiêu hao của Hủy Diệt. Chúng đồng loạt tràn về hướng được chỉ và lấp kín hành lang, những kẻ phía sau bước thẳng qua chỗ kẻ phía trước ngã xuống.",
  "relic.raitia-wind.researcherTitle": "Nhà nghiên cứu",
  "relic.raitia-wind.unlockRecord": "Hồ sơ nhận dạng 211. Xác nhận thuộc Hủy Diệt. Đây là cá thể thắt nơ màu bạc hà giữa những chị em mặc cùng kiểu đồ ngủ có mũ trùm; đứng khoanh tay, miệng mím chặt. Cô chỉ miễn cưỡng đi theo sau khi các chị em đã ùa về phía thức ăn, vậy mà đến nơi lại là người gặm bằng răng cửa lâu nhất. Chưa từng thấy cô dùng tiếng răng cửa để báo hiệu điều gì.",
